// WHAT USES THEM
//   PfxHelper::PfxHelper @0x82408348 builds all four helper programs and binds
//   their named constants:
//       CreateProgram(0, &unk_82044240, 288) -> m_quadVertexProgram  "uvOffset"
//       CreateProgram(1, &unk_820444F8, 688) -> m_9tapPixelProgram
//              "sampleOffsets4x4_1" / "sampleOffsets4x4_2" / "sampleOffsets4_1"
//       CreateProgram(1, &unk_820447A8, 948) -> m_16tapPixelProgram
//              "sampleOffsets_1" .. "sampleOffsets_4"
//       CreateProgram(1, &unk_82044360, 408) -> m_4tapPixelProgram
//              "sampleOffsets"
//   DepthOfField::DepthOfField @0x82402CA8 builds the fifth:
//       CreateProgram(1, &unk_82043FB8, 644) -> m_depthOfFieldProgram
//              "g_focalConstants1" / "g_focalConstants2"
//   The consumers are PfxHelper::Blur9 (the 9-tap), PfxHelper::DownSample (the
