//     fxc /nologo /T ps_3_0 /E mainBlur9PS  /O2 /Zpr /Fo helper_blur9_ps.fxo  brn_postfx_helper.fx
//     fxc /nologo /T ps_3_0 /E mainBlur16PS /O2 /Zpr /Fo helper_blur16_ps.fxo brn_postfx_helper.fx
